import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as Avatar from "../../ui/shadcn-avatar";
import * as Empty from "../../ui/empty";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

const buttonClasses =
  "inline-flex cursor-pointer items-center rounded-lg bg-gray-950 px-3 py-2 text-sm font-medium text-white transition hover:bg-gray-800 focus:outline-none focus-visible:ring-2 focus-visible:ring-accent-600";

export const view = Submodel.defineView<Model, Message>((): Html => {
  const h = html<Message>();

  return Empty.view<Message>({
    title: "No Team Members",
    description: "Invite your team to collaborate on this project.",
    media: Avatar.groupView<Message>([
      Avatar.view<Message>({ fallback: "CN" }),
      Avatar.view<Message>({ fallback: "LR" }),
      Avatar.view<Message>({ fallback: "ER" }),
    ]),
    mediaClasses: "bg-transparent p-0",
    action: h.button(
      [h.Type("button"), h.Class(buttonClasses)],
      ["Invite Members"]
    ),
  });
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as EmptyAvatarGroupExample from "./main";

describe("Empty Avatar Group example", () => {
  test("matches the upstream empty avatar group example content", () => {
    Scene.scene(
      {
        update: EmptyAvatarGroupExample.update,
        view: EmptyAvatarGroupExample.view,
      },
      Scene.with(EmptyAvatarGroupExample.init()[0]),
      Scene.expect(Scene.text("CN")).toExist(),
      Scene.expect(Scene.text("LR")).toExist(),
      Scene.expect(Scene.text("ER")).toExist(),
      Scene.expect(
        Scene.role("heading", { name: "No Team Members" })
      ).toExist(),
      Scene.expect(
        Scene.text("Invite your team to collaborate on this project.")
      ).toExist(),
      Scene.expect(Scene.role("button", { name: "Invite Members" })).toExist(),
      Scene.expect(
        Scene.role("button", { name: "Invite Members" })
      ).not.toHaveHandler("click")
    );
  });
});
